#include "stdafx.h"#include "HcdElementBase.h"struct STGFF_P{#include "PrivateVars/TGFF.h"};class KTGFF : public KHcdElementBase  , protected STGFF_P{public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void StepCalc( SStepCalcParams &params );};static KHcdFactory _TGFF("TGFF", KTGFF::Create);IHcdElement *KTGFF::Create(){  return new KTGFF;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KTGFF, 4 )void KTGFF::InitParm(){#include "PrivateVars/TGFF.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KTGFF::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;}void KTGFF::StepCalc( SStepCalcParams &params ){  if( RESET )    OUT = 0;  else  {    if( !OUT )    {      if( !prevTOG && TOG )        OUT = 1;    }    else    {      if( prevTOG && !TOG )        OUT = 0;    }  }  prevTOG = TOG;}